    cambiar = "\u00dasalo solo si tienes una raz\u00f3n documentada, por ejemplo eliminar palabras con peso casi nulo en todo el corpus.",
    cambia = "Excluye palabras del vocabulario. Siempre usa la media de todos los textos, aunque elijas otro resumen para ordenar.",
    comprobar = "Revisa la lista de palabras excluidas por este motivo y comprueba que no son t\u00e9rminos centrales de tu pregunta.",
    ejemplo = "Con un umbral de 0,01 se excluye toda palabra cuyo peso medio sea menor; palabras muy extendidas, con rareza baja, pueden caer aunque sean importantes.",
    tecnica = "Umbral sobre el TF-IDF medio global (tf relativo \u00d7 ln(N/df)), incluyendo ceros. No depende del resumen elegido para ordenar."),
