    cambiar = "Usa \u00abSe repiten m\u00e1s\u00bb para el volumen de menciones y \u00abDistinguen m\u00e1s los textos\u00bb para vocabulario caracter\u00edstico.",
    cambia = "Solo el orden de la vista y de sus gr\u00e1ficos. No cambia el vocabulario ni los modelos.",
